using System.Windows;
using System.Windows.Controls;
using DomainConsole.Shared;
namespace DomainConsole;
public sealed class DownloadSettings {public bool AutomaticRecovery {get;set;}public int NoMovementMinutes {get;set;}=10;}
public partial class MainWindow {
 void SaveDownloadSettings_Click(object sender,RoutedEventArgs e)=>Guard(()=>{
  if(!int.TryParse(DownloadWaitBox.Text,out var minutes)||minutes<10||minutes>180)throw new Exception("Порог: 10–180 минут.");
  Store.Write("download-settings.json",new DownloadSettings{AutomaticRecovery=AutomaticDownloadRecovery.IsChecked==true,NoMovementMinutes=minutes});
  Notify("Настройки сохранены. Одна автоматическая попытка для каждого задания BITS.");
 });
 public static string PriorityScript(string id,bool restore){if(!Guid.TryParse(id,out _))throw new ArgumentException("Неверный ID BITS");return "$ErrorActionPreference='Stop';$id=[guid]"+PowerShellBridge.Literal(id)+";$j=Get-BitsTransfer -AllUsers|Where-Object {$_.JobId -eq $id -and $_.DisplayName -eq 'WU Client Download' -and $_.OwnerAccount -match '(?i)(SYSTEM|СИСТЕМА)$'};if(!$j){throw 'Задание Windows Update уже отсутствует; обновите снимок'};$root=Join-Path $env:ProgramData 'DomainConsoleCSharp\\Controls';New-Item $root -ItemType Directory -Force|Out-Null;$path=Join-Path $root ('priority-'+$id+'.json');"+(restore?"if(!(Test-Path $path)){throw 'Исходный приоритет не сохранён'};$saved=Get-Content $path -Raw|ConvertFrom-Json;$j|Set-BitsTransfer -Priority $saved.Priority|Out-Null;Remove-Item $path -Force;'Исходный приоритет восстановлен: '+$saved.Priority":"if(!(Test-Path $path)){@{Id=[string]$id;Priority=[string]$j.Priority;ChangedUtc=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json|Set-Content $path -Encoding UTF8};$j|Set-BitsTransfer -Priority Foreground|Out-Null;'Ускоренный режим Foreground включён для выбранного задания. Ограничения сервера и сети сохраняются.'");}
 async void DownloadPriority_Click(object sender,RoutedEventArgs e)=>await Guard(async()=>{var row=Current();if(!backgroundUpdates.TryGetValue(row.Host,out var live)||!FreshActivity(live)){await RefreshBackground();live=backgroundUpdates.GetValueOrDefault(row.Host);};if(live==null||!FreshActivity(live)||live.Downloads.Count==0)throw new Exception("Нужен свежий снимок BITS выбранного компьютера.");var panel=new StackPanel{Margin=new(16)};var list=new ComboBox{ItemsSource=live.Downloads.Where(d=>d.Accelerated||(d.State is "Queued" or "Connecting" or "Transferring")).ToList(),DisplayMemberPath="Label",SelectedIndex=0,Margin=new(0,8,0,8)};panel.Children.Add(new TextBlock{Text="Выберите задание BITS. Foreground может занять доступную полосу, включая ограниченный 3G. Смена приоритета не меняет политику стоимости и не гарантирует ускорение.",TextWrapping=TextWrapping.Wrap});panel.Children.Add(list);bool restore=false;var w=new Window{Owner=this,Title="Скорость загрузки",Width=500,SizeToContent=SizeToContent.Height,Content=panel,WindowStartupLocation=WindowStartupLocation.CenterOwner};foreach(var choice in new[]{("Ускорить выбранное задание",false),("Вернуть исходный приоритет",true)}){var b=new Button{Content=choice.Item1,Margin=new(0,3,0,3)};b.Click+=(s,a)=>{restore=choice.Item2;w.DialogResult=true;};panel.Children.Add(b);}if(w.ShowDialog()!=true||list.SelectedItem is not BackgroundDownload download)return;MicrosoftBox.IsChecked=false;await Submit(new(){new(){Name=restore?"Возврат скорости BITS":"Ускорение BITS",Kind="PowerShell",Code=PriorityScript(download.Id,restore)}},"Commands",true);});
}
